from tools_b import *
qid,vid=sys.argv[1:3];out=HERE/qid/vid
cfg,ad=adapter();check=eligibility(qid);assert check['eligible'];before=inputs(ad,qid);meta=ad.inspect_question(qid)
plugin=json.loads((out/'plugin.json').read_text(encoding='utf-8'));renderer=PluginRenderer(cfg,ad,{qid:meta})
n,png,pixels=renderer.render(plugin,frozen=True);n2,png2,pixels2=renderer.render(plugin,frozen=True)
assert n==n2==plugin and png==png2==(out/'candidate.png').read_bytes() and pixels==pixels2
assert before==inputs(ad,qid)
write(out/'render_check.json',{'question_id':qid,'baseline_pixel_match':True,'schema_default_normalized':True,'two_byte_identical_redraws':True,'existing_candidate_reproduced_byte_identically':True,'png_sha256':file_hash(out/'candidate.png'),'pixel_sha256':pixels,'plugin_sha256':file_hash(out/'plugin.json'),'design_sha256':file_hash(out/'design.json'),'input_fingerprints':before,'isolation':ISOLATION,'geometry_fill_labels_unchanged':True,'appearance_actions':plugin['params']['actions'],'note':'The initial runtime reporter tried a Solid-only appearance_changes helper after saving the successfully rendered frozen Plane image. That reporting AttributeError did not change the image or inputs. This fresh read-only replay supplies its missing report; no API was called before it.'})
write(HERE/'render_preparation_errors.json',{'events':[{'path':'Plane226/separated_star_pair','status':'serialization_error_before_candidate_png_or_design_saved','reason':'Raw object_paths included ndarray controls; retained incomplete JSON is diagnostic only. Replaced the runtime serializer with exact ID/hash/closed snapshots plus full fresh context; no renderer/schema changes.'},{'path':'Plane226/separated_star_pair_frozen','status':'reporter_AttributeError_after_successful_png_and_design_save','reason':'Plane PluginRenderer has no Solid appearance_changes method. The candidate was subsequently reproduced byte-identically twice and this report supplied; no solver call or PNG change.'},{'question_id':'Plane234','status':'schema_rejection_before_candidate_save','reason':'Numeric-leading option ID3ray0 is not accepted as a style target by unchanged schema. Legal add_line overlays now use the exact existing sides from fresh context, with readable semantic fills untouched. No failed or tested PNG was retried.'}]})
print(json.dumps({'qid':qid,'variant':vid,'reproduced':True}),flush=True)
